//! `svc forge export` (done-criterion 1): the catalog `crates/svc-forge` serves, produced
//! from this store so the browser shows *this* repository rather than a fixture. The shape
//! is `svc_forge::Catalog`'s serde form, written here as JSON so `svc-repo` needs no
//! dependency on the web crate; operations, conflicts and review items are the `svc-core`
//! types the forge deserialises. Heads and the root carry their entities; ancestors are
//! listed bare so a long history on a large crate stays a small file. The forge reads the
//! file, never the store, so it can never contend with a writer.

use std::collections::{BTreeSet, VecDeque};
use std::path::{Path, PathBuf};

use serde_json::{Value, json};
use svc_core::engine::render_entity;
use svc_core::{Conflict, EntityId, Error, NoteKind, Op, OpIx, OpLogEntry, RelPath, ReviewItem, Result, Snapshot, SnapshotId, Store};

use crate::history::{op_entity, touch, touches};
use crate::repo::Repo;

/// How many ancestor snapshots to list beyond the heads and the root.
const ANCESTOR_LIMIT: usize = 200;

pub fn catalog(repo: &Repo) -> Result<Value> {
    let store = repo.store();
    let view = repo.view()?;
    let mut full: BTreeSet<SnapshotId> = view.heads.values().copied().collect();
    full.insert(view.root);

    // Breadth-first over parents and predecessors from every head and the root.
    let mut order: Vec<SnapshotId> = Vec::new();
    let mut seen: BTreeSet<SnapshotId> = BTreeSet::new();
    // Root first, then the other heads, then ancestors.
    let mut queue: VecDeque<SnapshotId> = VecDeque::from([view.root]);
    queue.extend(full.iter().copied().filter(|id| *id != view.root));
    while let Some(id) = queue.pop_front() {
        if !seen.insert(id) {
            continue;
        }
        order.push(id);
        if order.len() > full.len() + ANCESTOR_LIMIT {
            break;
        }
        if let Ok(s) = store.get_snapshot(id) {
            queue.extend(s.parents.iter().chain(s.predecessors.iter()).copied());
        }
    }

    let mut snapshots = Vec::with_capacity(order.len());
    for id in &order {
        let s = store.get_snapshot(*id)?;
        let entities: Vec<Value> = if full.contains(id) {
            s.entities
                .iter()
                .map(|(eid, rec)| {
                    let mut v = serde_json::to_value(rec).unwrap_or(Value::Null);
                    if let Value::Object(m) = &mut v {
                        m.insert("id".into(), json!(eid));
                        if let Some(text) = source(store, &s, *eid) {
                            m.insert("source".into(), Value::String(text));
                        }
                    }
                    v
                })
                .collect()
        } else {
            Vec::new()
        };
        snapshots.push(json!({
            "id": id,
            "change": s.change,
            "message": s.message,
            "parents": s.parents,
            "entities": entities,
            "conflicts": s.conflicts,
        }));
    }

    let ops = store.ops(OpIx(0), false)?;
    let operations: Vec<Value> = ops
        .iter()
        .map(|(ix, e)| {
            let ws = repo.redb().op_workspace(*ix).ok().flatten().filter(|w| !w.is_empty());
            operation(store, *ix, e, ws.as_deref())
        })
        .collect();

    // The review queue as the review rules define it: every edit-def, and every binding conflict
    // in the current snapshot. (Changesets' own `queue` is not populated by any verb.)
    let mut review: Vec<ReviewItem> = ops
        .iter()
        .filter_map(|(ix, e)| match &e.op {
            Op::EditDef { intent, .. } => Some(ReviewItem::EditReview {
                op: *ix,
                declared: intent.clone(),
                observed: e.observed,
                ask_id: None,
            }),
            Op::Note { to, kind, text } if !matches!(kind, NoteKind::Claim | NoteKind::Release) => {
                Some(ReviewItem::Note {
                    op: *ix,
                    to: to.clone(),
                    kind: kind.clone(),
                    text: text.clone(),
                })
            }
            _ => None,
        })
        .collect();
    let cur = repo.current()?;
    review.extend(cur.conflicts.iter().filter(|c| matches!(c, Conflict::Binding { .. })).map(|c| ReviewItem::BindingConflict { conflict: c.clone() }));

    // What every checkout is on: this one's root plus the named workspaces' — the
    // forge marks those changes current, not every change that still has a head.
    let mut checkouts = vec![view.root];
    checkouts.extend(repo.redb().workspaces()?.into_iter().filter_map(|(_, w)| w.root));
    let root = repo.root_dir();
    let name = root.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_else(|| "repo".into());
    let slug: String = name.chars().map(|c| if c.is_ascii_alphanumeric() { c.to_ascii_lowercase() } else { '-' }).collect();
    Ok(json!({
        "repositories": [{
            "slug": slug,
            "name": name,
            "path": root,
            "description": format!("{} entities, {} operations, {} changes", cur.entities.len(), ops.len(), view.heads.len()),
            "head": view.root,
            "heads": checkouts,
            "snapshots": snapshots,
            "operations": operations,
            "review_queue": review,
        }]
    }))
}

/// The entity's rendered text, for the browser's entity and change pages.
fn source(store: &dyn Store, snap: &Snapshot, id: EntityId) -> Option<String> {
    render_entity(snap, store, id, false)
        .ok()
        .map(|(bytes, _)| String::from_utf8_lossy(&bytes).into_owned())
}

/// The raw log entry plus what the browser needs beside it: `ix`, the after-root's `change`,
/// and for an op about one entity a `subject` with its names, kind, file, both sources and
/// the touch — so a change page can show a rename or edit without opening the store.
fn operation(store: &dyn Store, ix: OpIx, e: &OpLogEntry, workspace: Option<&str>) -> Value {
    let mut v = serde_json::to_value(e).unwrap_or(Value::Null);
    let Value::Object(m) = &mut v else { return v };
    m.insert("ix".into(), json!(ix));
    let after = store.get_snapshot(e.after.root).ok();
    if let Some(after) = &after {
        m.insert("change".into(), json!(after.change));
    }
    if let Some(name) = e.group.and_then(|g| store.get_changeset(g).ok()).map(|cs| cs.name) {
        m.insert("group_name".into(), json!(name));
    }
    if let Some(w) = workspace {
        m.insert("workspace".into(), json!(w));
    }
    // Every entity the op touched and every opaque file it changed, so an absorb or a
    // merge — the ops that carry other people's work — has names and paths too.
    let before = store.get_snapshot(e.before.root).ok();
    if let (Some(b), Some(a)) = (&before, &after) {
        let touched = touches(b, a, e.observed);
        if !touched.is_empty() {
            // Each touch carries the entity's text on both sides when the op changed it, so
            // a change page can show an absorb entity by entity. `New` is the init op with
            // everything "added": its texts are the snapshot's, not a change.
            let with_text = !matches!(e.op, Op::New { .. } | Op::Describe { .. } | Op::Branch { .. });
            let subjects: Vec<Value> = touched
                .iter()
                .map(|t| {
                    let mut v = serde_json::to_value(t).unwrap_or(Value::Null);
                    let Value::Object(sm) = &mut v else { return v };
                    let prev = b.entities.get(&t.entity);
                    let next = a.entities.get(&t.entity);
                    if let Some(r) = next.or(prev) {
                        sm.insert("kind".into(), json!(r.kind));
                        sm.insert("file".into(), json!(r.file));
                    }
                    if with_text {
                        let before_text = prev.and_then(|_| source(store, b, t.entity));
                        let after_text = next.and_then(|_| source(store, a, t.entity));
                        if before_text != after_text {
                            if let Some(x) = before_text {
                                sm.insert("before_source".into(), Value::String(x));
                            }
                            if let Some(x) = after_text {
                                sm.insert("after_source".into(), Value::String(x));
                            }
                        }
                    }
                    v
                })
                .collect();
            m.insert("subjects".into(), Value::Array(subjects));
        }
        let changed: Vec<&RelPath> = a
            .files
            .iter()
            .filter(|(p, rec)| b.files.get(*p) != Some(rec))
            .map(|(p, _)| p)
            .chain(b.files.keys().filter(|p| !a.files.contains_key(*p)))
            .collect();
        if !changed.is_empty() {
            m.insert("files".into(), json!(changed));
        }
    }
    if let (Some(id), Some(after)) = (op_entity(&e.op), &after) {
        let prev = before.as_ref().and_then(|b| b.entities.get(&id));
        let next = after.entities.get(&id);
        let shown = next.or(prev);
        // Absent rather than null: the browser's fields default when a key is missing.
        let mut subject = serde_json::Map::new();
        subject.insert("id".into(), json!(id));
        let mut put = |key: &str, value: Option<Value>| {
            if let Some(v) = value {
                subject.insert(key.into(), v);
            }
        };
        put("before_name", prev.map(|r| json!(r.name)));
        put("after_name", next.map(|r| json!(r.name)));
        put("kind", shown.map(|r| json!(r.kind)));
        put("file", shown.map(|r| json!(r.file)));
        put("before_source", before.as_ref().and_then(|b| source(store, b, id)).map(Value::String));
        put("after_source", source(store, after, id).map(Value::String));
        put("touch", touch(prev, next, e.observed).map(|t| json!(t)));
        m.insert("subject".into(), Value::Object(subject));
    }
    v
}

/// Write the catalog; default `.svc/forge.json` under the repository root.
pub fn export(repo: &Repo, out: Option<&Path>) -> Result<PathBuf> {
    let path = out.map(Path::to_path_buf).unwrap_or_else(|| repo.root_dir().join(".svc/forge.json"));
    let text = serde_json::to_string_pretty(&catalog(repo)?).map_err(|e| Error::Other(e.to_string()))?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| Error::Other(e.to_string()))?;
    }
    // Atomic replace: the forge may be reading the old file.
    let tmp = path.with_extension("json.tmp");
    std::fs::write(&tmp, text).map_err(|e| Error::Other(e.to_string()))?;
    std::fs::rename(&tmp, &path).map_err(|e| Error::Other(e.to_string()))?;
    Ok(path)
}

crates/svc-repo/src/history.rs.Text:
//! History verbs: jj-style changes over immutable snapshots.
//!
//! `evolog` walks `Snapshot.predecessors` — the *rewrite* chain of one change — never
//! `parents`. `Store::evolog` follows `predecessors.first()`, which is exact as long as an
//! amend records exactly one predecessor (it does: [`Repo::amend`]).

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use svc_core::delta::Delta;
use svc_core::engine::status_report;
use svc_core::{
    ChangeId, ChangeSetId, EntityId, EntityRecord, Error, Intent, NoteKind, NoteTo, ObservedClass,
    Op, OpIx, OpLogEntry, RelPath, Result, Snapshot, SnapshotId, Timestamp, View,
};

use crate::repo::{Mutation, Repo};
use crate::workspace::DEFAULT_WORKSPACE;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ChangeOut {
    pub change: ChangeId,
    pub short: String,
    pub snapshot: SnapshotId,
    pub message: String,
    pub branches: Vec<String>,
    pub current: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct OpOut {
    pub ix: OpIx,
    pub op: Op,
    pub declared: Option<Intent>,
    pub observed: Option<ObservedClass>,
    pub flagged: bool,
    pub at: Timestamp,
    pub group: Option<ChangeSetId>,
    pub root_after: SnapshotId,
    /// The entity's name *before* the op (renames need it; the current snapshot has the new one).
    pub subject: Option<String>,
    /// The checkout that made it (absent = the default one).
    #[serde(default)]
    pub workspace: Option<String>,
}

/// How one op or rewrite touched one entity. `Edited.observed` is the op log's verdict
/// for that op, absent when nothing classified it (a hand edit, or a class not yet landed).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Touch {
    Added,
    Removed,
    Renamed { from: String, to: String },
    Moved { from: Option<EntityId>, to: Option<EntityId> },
    Relocated { from: (RelPath, u32), to: (RelPath, u32) },
    Edited { observed: Option<ObservedClass> },
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct EntityTouch {
    pub entity: EntityId,
    pub name: String,
    pub touch: Touch,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct EvologEntry {
    pub snapshot: SnapshotId,
    pub message: String,
    pub entities: usize,
    /// Versus the previous (older) entry; empty for the first.
    pub deltas: Vec<EntityTouch>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BlameEntry {
    pub ix: OpIx,
    pub change: ChangeId,
    pub op: Op,
    pub touch: Touch,
    pub at: Timestamp,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MutationOut {
    pub ix: OpIx,
    pub change: ChangeId,
    pub snapshot: SnapshotId,
    pub closed_stale_changeset: Option<ChangeSetId>,
}

impl MutationOut {
    fn of(repo: &Repo, m: Mutation) -> Result<Self> {
        Ok(Self {
            ix: m.ix,
            change: repo.store().get_snapshot(m.entry.after.root)?.change,
            snapshot: m.snapshot,
            closed_stale_changeset: m.closed_stale_changeset,
        })
    }
}

fn op_out(repo: &Repo, ix: OpIx, e: &OpLogEntry) -> OpOut {
    let store = repo.store();
    // Name as of just before the op (so a rename shows its old name); for ops that create
    // the entity (add-def, extract) fall back to the name just after. Stored on the entry
    // so the line stays readable after the entity is later deleted or the op undone.
    let subject = op_entity(&e.op).and_then(|id| {
        let name_in = |root| {
            store
                .get_snapshot(root)
                .ok()
                .and_then(|s| s.entities.get(&id).map(|r| r.name.clone()))
        };
        name_in(e.before.root).or_else(|| name_in(e.after.root))
    });
    OpOut {
        ix,
        subject,
        declared: e.declared().cloned(),
        observed: e.observed,
        flagged: e.flagged(),
        at: e.at,
        group: e.group,
        root_after: e.after.root,
        op: e.op.clone(),
        workspace: repo.redb().op_workspace(ix).ok().flatten().filter(|w| !w.is_empty()),
    }
}

pub(crate) fn child_of(cur: &Snapshot, cur_id: SnapshotId, change: ChangeId) -> Snapshot {
    Snapshot {
        parents: vec![cur_id],
        predecessors: Vec::new(),
        change,
        entities: cur.entities.clone(),
        files: cur.files.clone(),
        conflicts: cur.conflicts.clone(),
        message: String::new(),
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct StatusOut {
    pub summary: String,
    pub entities: usize,
    pub layout: usize,
    pub semantic: usize,
    pub clean: bool,
    pub change: ChangeId,
    pub snapshot: SnapshotId,
    /// Semantic deltas versus the snapshot before this status (layout-only ordinal shifts suppressed).
    pub deltas: Vec<Delta>,
    pub absorbed: bool,
    /// Unresolved merge conflicts on the current snapshot (`svc conflicts` lists them).
    pub conflicts: usize,
    /// Other checkouts' live claims on entities in this tree (`svc claim`).
    #[serde(default)]
    pub claims: Vec<ClaimOut>,
    /// Unread mail/review notes addressed here or `@all`.
    #[serde(default)]
    pub inbox: usize,
}

/// `svc status`: absorb hand edits into the current change (recording an `Absorb` op) and
/// report what changed. Identical content is a no-op.
pub fn status(repo: &Repo) -> Result<StatusOut> {
    let (report, snap, absorbed) = match repo.absorb()? {
        Some((prev, id)) => {
            let next = repo.store().get_snapshot(id)?;
            (status_report(repo.store(), &prev, &next)?, next, true)
        }
        None => {
            let cur = repo.current()?;
            (status_report(repo.store(), &cur, &cur)?, cur, false)
        }
    };
    Ok(StatusOut {
        summary: report.summary(),
        entities: report.entities,
        layout: report.layout,
        semantic: report.semantic,
        clean: report.deltas.is_empty(),
        change: snap.change,
        snapshot: snap.id(),
        deltas: report.deltas,
        absorbed,
        conflicts: snap.conflicts.len(),
        claims: active_claims(repo)?,
        inbox: inbox(repo)?.unread.len(),
    })
}

/// `svc new`: start the next change on top of the current one.
pub fn new(repo: &Repo) -> Result<MutationOut> {
    let change = ChangeId::new();
    let m = repo.mutate(Op::New { change }, None, |repo, cur| {
        repo.commit_snapshot(&child_of(cur, cur.id(), change))
    })?;
    MutationOut::of(repo, m)
}

/// `svc describe`: set the current change's message (an amend).
pub fn describe(repo: &Repo, msg: &str) -> Result<MutationOut> {
    let m = repo.mutate(Op::Describe { msg: msg.into() }, None, |repo, cur| {
        let mut next = cur.clone();
        next.message = msg.into();
        repo.amend(cur, next)
    })?;
    MutationOut::of(repo, m)
}

/// `svc branch <name>`: a new change that is a *sibling* of the current one — its parent is
/// the current change's parent — named `name`, and made current. A root
/// change has no parent, so its sibling would be empty; branch from the root itself instead.
pub fn branch(repo: &Repo, name: &str) -> Result<MutationOut> {
    if repo.store().branch(name)?.is_some() {
        return Err(Error::Other(format!("branch {name:?} already exists")));
    }
    let change = ChangeId::new();
    let m = repo.mutate(Op::Branch { name: name.into() }, None, |repo, cur| {
        let (base, base_id) = match cur.parents.first() {
            Some(p) => (repo.store().get_snapshot(*p)?, *p),
            None => (cur.clone(), cur.id()),
        };
        let id = repo.commit_snapshot(&child_of(&base, base_id, change))?;
        repo.store().set_branch(name, change)?;
        Ok(id)
    })?;
    MutationOut::of(repo, m)
}

/// `svc edit <change|branch>`: make another change's head the working copy.
pub fn edit(repo: &Repo, target: &str) -> Result<View> {
    let change = repo.resolve_change(target)?;
    let head = repo.store().head(change)?;
    checkout(repo, head)
}

/// `svc checkout <snapshot>`: view a snapshot. Moves `root` only — no change, no head, no
/// op-log entry — and refuses to overwrite hand edits.
pub fn checkout(repo: &Repo, snapshot: SnapshotId) -> Result<View> {
    if !repo.working_copy_clean()? {
        return Err(Error::Other(
            "working copy has edits not yet snapshotted; run `svc status` first".into(),
        ));
    }
    let snap = repo.store().get_snapshot(snapshot)?;
    repo.store().set_render_pending(true)?;
    repo.store().set_root(snapshot)?;
    repo.render_to_disk(&snap)?;
    repo.store().set_render_pending(false)?;
    repo.view()
}

/// `svc heads`: every change and where it points, current first.
pub fn heads(repo: &Repo) -> Result<Vec<ChangeOut>> {
    let store = repo.store();
    let current = repo.current_change()?;
    let mut names: BTreeMap<ChangeId, Vec<String>> = BTreeMap::new();
    for (name, id) in store.branches()? {
        names.entry(id).or_default().push(name);
    }
    let mut out = Vec::new();
    for (change, snapshot) in store.heads()? {
        out.push(ChangeOut {
            change,
            short: change.short(),
            snapshot,
            message: store.get_snapshot(snapshot)?.message,
            branches: names.remove(&change).unwrap_or_default(),
            current: change == current,
        });
    }
    out.sort_by_key(|c| !c.current);
    Ok(out)
}

/// `svc op log`: the unscoped journal, newest first.
pub fn op_log(repo: &Repo) -> Result<Vec<OpOut>> {
    Ok(repo
        .store()
        .ops(OpIx(0), true)?
        .iter()
        .map(|(ix, e)| op_out(repo, *ix, e))
        .collect())
}

/// `svc log`: the op view scoped to one change — every op that moved that
/// change's head or ran on it (a no-op `edit-def` still happened and still queues for
/// review) — newest first. Defaults to the current change.
pub fn log(repo: &Repo, change: Option<ChangeId>) -> Result<Vec<OpOut>> {
    let change = match change {
        Some(c) => c,
        None => repo.current_change()?,
    };
    let store = repo.store();
    let on_change = |e: &OpLogEntry| {
        e.before.heads.get(&change) != e.after.heads.get(&change)
            || store.get_snapshot(e.after.root).is_ok_and(|s| s.change == change)
    };
    Ok(store
        .ops(OpIx(0), true)?
        .iter()
        .filter(|(_, e)| on_change(e))
        // The change's birth is not one of its events.
        .filter(|(_, e)| !matches!(e.op, Op::New { .. } | Op::Branch { .. }))
        .map(|(ix, e)| op_out(repo, *ix, e))
        .collect())
}

/// `svc log <entity>`: blame at entity granularity — which ops touched it and how.
pub fn blame(repo: &Repo, entity: EntityId) -> Result<Vec<BlameEntry>> {
    let store = repo.store();
    let mut out = Vec::new();
    for (ix, e) in store.ops(OpIx(0), true)? {
        if e.before.root == e.after.root {
            continue;
        }
        let before = store.get_snapshot(e.before.root)?;
        let after = store.get_snapshot(e.after.root)?;
        if let Some(touch) = touch(
            before.entities.get(&entity),
            after.entities.get(&entity),
            e.observed,
        ) {
            out.push(BlameEntry {
                ix,
                change: after.change,
                op: e.op.clone(),
                touch,
                at: e.at,
            });
        }
    }
    Ok(out)
}

/// `svc evolog <change>`: the change's snapshots newest first, each with what it changed
/// versus the one it rewrote.
pub fn evolog(repo: &Repo, change: ChangeId) -> Result<Vec<EvologEntry>> {
    let store = repo.store();
    let snaps = store.evolog(change)?;
    let ops = store.ops(OpIx(0), false)?;
    let mut out = Vec::with_capacity(snaps.len());
    for (i, snap) in snaps.iter().enumerate() {
        let id = snap.id();
        let observed = ops
            .iter()
            .find(|(_, e)| e.after.heads.get(&change) == Some(&id))
            .and_then(|(_, e)| e.observed);
        let deltas = match snaps.get(i + 1) {
            Some(prev) => touches(prev, snap, observed),
            None => Vec::new(),
        };
        out.push(EvologEntry {
            snapshot: id,
            message: snap.message.clone(),
            entities: snap.entities.len(),
            deltas,
        });
    }
    Ok(out)
}

/// `svc undo`: restore the view from before this checkout's newest op that no earlier undo
/// already reverted; an op that belongs to a changeset takes the whole group with it.
/// Redo is `svc op restore <n>`.
pub fn undo(repo: &Repo) -> Result<MutationOut> {
    // Each checkout undoes its own ops: another checkout's entry carries
    // *its* root in `before`, and restoring that here would silently switch checkouts.
    // Unattributed entries from before op attribution count as the default checkout's.
    let ops = repo.redb().own_ops(OpIx(0), true)?;
    // Repeated `undo` keeps walking back (as `jj undo` does since 0.29) instead of undoing
    // the previous undo: skip every op an earlier undo already reverted. An undo of a
    // changeset reverts the whole group, so it cancels that many ops.
    let entries: Vec<&OpLogEntry> = ops.iter().map(|(_, e)| e).collect(); // newest first
    let mut i = 0;
    let mut pending = 0usize;
    let first = loop {
        let Some(e) = entries.get(i) else {
            return Err(Error::Other("nothing to undo".into()));
        };
        if matches!(e.op, Op::Undo) {
            pending += 1;
            i += 1;
        } else if pending > 0 {
            // reverted by an earlier undo — together with the rest of its changeset
            pending -= 1;
            let g = e.group;
            i += 1;
            while g.is_some() && entries.get(i).is_some_and(|n| n.group == g) {
                i += 1;
            }
        } else {
            break i;
        }
    };
    let last = entries[first];
    let target = match last.group {
        Some(g) => entries[first..]
            .iter()
            .take_while(|e| e.group == Some(g))
            .last()
            .copied()
            .unwrap_or(last),
        None => last,
    };
    if target.before.heads.is_empty() {
        return Err(Error::Other("cannot undo init".into()));
    }
    // Only what the undone ops moved goes back: this checkout's root and the heads whose
    // value differs across the range. Another checkout's head that moved since is its
    // business, not something an undo here may rewind.
    let mut view = repo.view()?;
    view.root = target.before.root;
    for (change, snap) in &target.before.heads {
        if last.after.heads.get(change) != Some(snap) {
            view.heads.insert(*change, *snap);
        }
    }
    let m = repo.restore_view(&view, Op::Undo)?;
    MutationOut::of(repo, m)
}

/// `svc op restore <n>`: return to the view as it stood right after op `n`.
pub fn op_restore(repo: &Repo, ix: OpIx) -> Result<MutationOut> {
    let entry = repo
        .store()
        .ops(ix, false)?
        .into_iter()
        .find(|(i, _)| *i == ix)
        .map(|(_, e)| e)
        .ok_or_else(|| Error::NotFound(format!("op {}", ix.0)))?;
    let m = repo.restore_view(&entry.after, Op::Restore { at: ix.0 })?;
    MutationOut::of(repo, m)
}

/// Attribute-level difference of one entity between two snapshots. Content that moved
/// without any attribute moving is `Edited`.
pub fn touch(
    prev: Option<&EntityRecord>,
    next: Option<&EntityRecord>,
    observed: Option<ObservedClass>,
) -> Option<Touch> {
    match (prev, next) {
        (None, None) => None,
        (None, Some(_)) => Some(Touch::Added),
        (Some(_), None) => Some(Touch::Removed),
        (Some(a), Some(b)) => {
            if a.name != b.name {
                Some(Touch::Renamed {
                    from: a.name.clone(),
                    to: b.name.clone(),
                })
            } else if a.parent != b.parent {
                Some(Touch::Moved {
                    from: a.parent,
                    to: b.parent,
                })
            } else if a.file != b.file || a.ordinal != b.ordinal {
                Some(Touch::Relocated {
                    from: (a.file.clone(), a.ordinal),
                    to: (b.file.clone(), b.ordinal),
                })
            } else if a.content != b.content || a.bytes != b.bytes {
                Some(Touch::Edited { observed })
            } else {
                None
            }
        }
    }
}

/// Every entity `touch`ed between two snapshots, in id order.
pub fn touches(prev: &Snapshot, next: &Snapshot, observed: Option<ObservedClass>) -> Vec<EntityTouch> {
    let ids = prev.entities.keys().chain(next.entities.keys());
    let mut seen = std::collections::BTreeSet::new();
    let mut out = Vec::new();
    for id in ids {
        if !seen.insert(*id) {
            continue;
        }
        let a = prev.entities.get(id);
        let b = next.entities.get(id);
        if let Some(t) = touch(a, b, observed) {
            out.push(EntityTouch {
                entity: *id,
                name: b.or(a).map(|r| r.name.clone()).unwrap_or_default(),
                touch: t,
            });
        }
    }
    out
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ChangeSetOut {
    pub id: ChangeSetId,
    pub name: String,
    pub intent: Intent,
    pub description: String,
    pub open: bool,
    pub ops: Vec<OpOut>,
    /// Review/mail notes hung on this changeset (the other half of a PR).
    #[serde(default)]
    pub reviews: Vec<OpOut>,
}

/// `svc changeset begin <name>`: open a group that every following op is stamped with.
/// Refuses while another is open unless `force`; a stale row is closed first.
pub fn changeset_begin(
    repo: &Repo,
    name: &str,
    intent: Intent,
    pid: Option<u32>,
    force: bool,
) -> Result<ChangeSetOut> {
    let store = repo.store();
    if let (Some(open), _) = repo.open_group()? {
        if !force {
            return Err(Error::Other(format!(
                "changeset {} is already open; `svc changeset end` it or pass --force",
                open.short()
            )));
        }
    }
    let cs = svc_core::ChangeSet {
        id: ChangeSetId::new(),
        name: name.into(),
        intent,
        queue: Vec::new(),
        description: String::new(),
    };
    store.put_changeset(&cs)?;
    store.set_open_changeset(Some(svc_core::OpenChangeSet {
        id: cs.id,
        pid,
        opened_at: crate::repo::now(),
    }))?;
    changeset_out(repo, cs, true)
}

/// `svc changeset end`: close the open group. Returns what was closed, if anything.
pub fn changeset_end(repo: &Repo) -> Result<Option<ChangeSetId>> {
    let open = repo.store().open_changeset()?.map(|r| r.id);
    repo.store().set_open_changeset(None)?;
    Ok(open)
}

/// `svc changeset status`: the open group and its ops so far, or `None`.
pub fn changeset_status(repo: &Repo) -> Result<Option<ChangeSetOut>> {
    match repo.open_group()? {
        (Some(id), _) => changeset_out(repo, repo.store().get_changeset(id)?, true).map(Some),
        _ => Ok(None),
    }
}

/// `svc changesets`: every group, with its ops.
pub fn changesets(repo: &Repo) -> Result<Vec<ChangeSetOut>> {
    let open = repo.open_group()?.0;
    repo.store()
        .changesets()?
        .into_iter()
        .map(|cs| {
            let is_open = open == Some(cs.id);
            changeset_out(repo, cs, is_open)
        })
        .collect()
}

fn changeset_out(repo: &Repo, cs: svc_core::ChangeSet, open: bool) -> Result<ChangeSetOut> {
    let mut ops = Vec::new();
    let mut reviews = Vec::new();
    for (ix, e) in repo.store().ops(OpIx(0), true)? {
        let about = matches!(
            &e.op,
            Op::Note {
                to: NoteTo::Changeset(id),
                kind,
                ..
            } if *id == cs.id && !matches!(kind, NoteKind::Claim | NoteKind::Release)
        );
        if e.group == Some(cs.id) || about {
            let out = op_out(repo, ix, &e);
            if about {
                reviews.push(out.clone());
            }
            ops.push(out);
        }
    }
    Ok(ChangeSetOut {
        id: cs.id,
        name: cs.name,
        intent: cs.intent,
        description: cs.description,
        open,
        ops,
        reviews,
    })
}

/// Resolve an entity by name in the current snapshot, optionally qualified as
/// `Parent::name` (one level) to disambiguate methods of the same name.
/// `svc … --entity X`: an id, a name, `Parent::name` (the parent's name, or for an impl
/// block the type it is for), or `path/suffix.rs:name`. Ambiguity lists the candidates.
pub fn resolve_entity(repo: &Repo, arg: &str) -> Result<EntityId> {
    resolve_entity_in(&repo.current()?, arg)
}

/// [`resolve_entity`] against a chosen snapshot (a historical `--at`). An id or an id
/// prefix wins outright; names are matched exactly.
pub fn resolve_entity_in(snap: &Snapshot, arg: &str) -> Result<EntityId> {
    if let Some(id) = parse_entity_id(arg) {
        if snap.entities.contains_key(&id) {
            return Ok(id);
        }
    }
    let spec_hits: Vec<EntityId> = snap.entities.keys().copied().filter(|id| id.matches_spec(arg)).collect();
    let (file, rest) = match arg.rsplit_once(':').filter(|(f, _)| f.contains('/') || f.contains('.')) {
        Some((f, n)) if !f.ends_with(':') => (Some(f), n),
        _ => (None, arg),
    };
    let (parent, name) = match rest.rsplit_once("::") {
        Some((p, n)) => (Some(p), n),
        None => (None, rest),
    };
    let mut hits: Vec<EntityId> = snap
        .entities
        .iter()
        .filter(|(_, r)| r.name == name)
        .filter(|(_, r)| file.is_none_or(|f| r.file.as_str().ends_with(f)))
        .filter(|(_, r)| match parent {
            None => true,
            Some(p) => r
                .parent
                .and_then(|pid| snap.entities.get(&pid))
                .is_some_and(|pr| pr.name == p || impl_target(&pr.name) == Some(p)),
        })
        .map(|(id, _)| *id)
        .collect();
    hits.sort();
    match hits.len() {
        1 => Ok(hits[0]),
        0 if spec_hits.len() == 1 => Ok(spec_hits[0]),
        0 => Err(Error::NotFound(format!("entity {arg:?}"))),
        _ => {
            let listed: Vec<String> = hits
                .iter()
                .map(|id| {
                    let r = &snap.entities[id];
                    let parent = r
                        .parent
                        .and_then(|p| snap.entities.get(&p))
                        .map(|p| format!("{}::", impl_target(&p.name).unwrap_or(&p.name)))
                        .unwrap_or_default();
                    format!("{}:{parent}{} ⟨{}⟩", r.file, r.name, id.short())
                })
                .collect();
            Err(Error::Other(format!(
                "{arg:?} names {} entities — {}; qualify it as Parent::{name} or file.rs:{name}, or pass the id",
                hits.len(),
                listed.join(", ")
            )))
        }
    }
}

/// The type an impl block's synthesised name is for: `impl<Foo>` and `impl<Tr for Foo>` → `Foo`.
fn impl_target(name: &str) -> Option<&str> {
    let inner = name.strip_prefix("impl<")?.strip_suffix('>')?;
    Some(inner.rsplit_once(" for ").map_or(inner, |(_, t)| t))
}

pub fn parse_entity_id(s: &str) -> Option<EntityId> {
    s.parse::<uuid::Uuid>().ok().map(EntityId)
}

/// The entity an op is about, when it is about one.
pub fn op_entity(op: &Op) -> Option<EntityId> {
    match op {
        Op::Rename { id, .. }
        | Op::Move { id, .. }
        | Op::Relocate { id, .. }
        | Op::Extract { id, .. }
        | Op::Inline { id }
        | Op::AddDef { id, .. }
        | Op::Delete { id, .. }
        | Op::EditDef { id, .. } => Some(*id),
        Op::Note {
            to: NoteTo::Entity(id),
            ..
        } => Some(*id),
        _ => None,
    }
}

/// Whole-word mentions of `word` still in the rendered working copy after a rename. Every
/// reference svc resolved has already changed; what remains is what it could not resolve —
/// method calls on typed receivers (`x.word(…)`, which need types), and strings, comments
/// or unrelated bindings — and did not touch. The honest numbers to print next to
/// "renamed" (demo line 13), not to hide.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Mentions {
    pub method_calls: usize,
    pub other: usize,
}

pub fn untracked_mentions(repo: &Repo, word: &str) -> Result<Mentions> {
    let snap = repo.current()?;
    let is_ident = |c: char| c == '_' || c.is_ascii_alphanumeric();
    let mut m = Mentions::default();
    for path in snap.files.keys() {
        let Ok(text) = std::fs::read_to_string(repo.root_dir().join(path.as_str())) else {
            continue;
        };
        let mut from = 0;
        while let Some(i) = text[from..].find(word) {
            let start = from + i;
            let end = start + word.len();
            from = end;
            let head = &text[..start];
            let tail = &text[end..];
            if head.chars().next_back().is_some_and(is_ident) || tail.chars().next().is_some_and(is_ident) {
                continue;
            }
            let method_call = head.trim_end().ends_with('.') && tail.trim_start().starts_with('(');
            if method_call {
                m.method_calls += 1;
            } else {
                m.other += 1;
            }
        }
    }
    Ok(m)
}

/// The checkout name stamped on notes (`default` when this is the `.svc/` tree).
pub fn checkout_name(repo: &Repo) -> String {
    repo.workspace()
        .unwrap_or(DEFAULT_WORKSPACE)
        .to_string()
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ClaimOut {
    pub entity: EntityId,
    pub name: String,
    pub by: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct InboxOut {
    pub unread: Vec<OpOut>,
    pub cursor: u64,
}

/// Append a coordination op. Snapshot is unchanged; the log is the mailbox.
pub fn note(repo: &Repo, to: NoteTo, kind: NoteKind, text: impl Into<String>) -> Result<MutationOut> {
    let text = text.into();
    if matches!(kind, NoteKind::Note) && text.trim().is_empty() {
        return Err(Error::Other("note text is empty".into()));
    }
    let m = repo.mutate(
        Op::Note { to, kind, text },
        None,
        |_, cur| Ok(cur.id()),
    )?;
    MutationOut::of(repo, m)
}

pub fn resolve_changeset(repo: &Repo, spec: &str) -> Result<svc_core::ChangeSet> {
    let all = repo.store().changesets()?;
    let named: Vec<_> = all.iter().filter(|c| c.name == spec).cloned().collect();
    match named.len() {
        1 => return Ok(named.into_iter().next().unwrap()),
        n if n > 1 => {
            return Err(Error::Other(format!(
                "changeset {spec:?} names {n} groups — pass the id"
            )));
        }
        _ => {}
    }
    match svc_core::ids::resolve_spec(all.iter().map(|c| c.id), |id| {
        id.matches_spec(spec) || id.to_string() == spec
    }) {
        Ok(id) => all
            .into_iter()
            .find(|c| c.id == id)
            .ok_or_else(|| Error::NotFound(format!("changeset {spec:?}"))),
        Err(hits) if hits.is_empty() => Err(Error::NotFound(format!("changeset {spec:?}"))),
        Err(_) => Err(Error::Other(format!(
            "changeset {spec:?} is ambiguous — pass more of the id"
        ))),
    }
}

pub fn changeset_show(repo: &Repo, spec: &str) -> Result<ChangeSetOut> {
    let cs = resolve_changeset(repo, spec)?;
    let open = repo.open_group()?.0 == Some(cs.id);
    changeset_out(repo, cs, open)
}

/// `svc review <changeset> --approve|--request-changes|--note`.
pub fn review(
    repo: &Repo,
    spec: &str,
    kind: NoteKind,
    text: &str,
) -> Result<MutationOut> {
    if !matches!(
        kind,
        NoteKind::Approve | NoteKind::RequestChanges | NoteKind::Note
    ) {
        return Err(Error::Other("review kind must be approve, request-changes, or note".into()));
    }
    let cs = resolve_changeset(repo, spec)?;
    note(repo, NoteTo::Changeset(cs.id), kind, text)
}

/// `svc mail <checkout|@all> "<text>" [--about entity|changeset]`.
pub fn mail(
    repo: &Repo,
    to: &str,
    text: &str,
    about: Option<&str>,
) -> Result<MutationOut> {
    let dest = resolve_mail_to(repo, to, about)?;
    note(repo, dest, NoteKind::Note, text)
}

fn resolve_mail_to(repo: &Repo, to: &str, about: Option<&str>) -> Result<NoteTo> {
    if let Some(about) = about {
        if let Ok(id) = resolve_entity(repo, about) {
            return Ok(NoteTo::Entity(id));
        }
        if let Ok(cs) = resolve_changeset(repo, about) {
            return Ok(NoteTo::Changeset(cs.id));
        }
        return Err(Error::NotFound(format!(
            "--about {about:?} is not an entity or a changeset"
        )));
    }
    if to == "@all" {
        Ok(NoteTo::All)
    } else {
        Ok(NoteTo::Checkout(to.into()))
    }
}

fn note_is_mail(op: &Op) -> bool {
    match op {
        Op::Note { kind, .. } => !matches!(kind, NoteKind::Claim | NoteKind::Release),
        _ => false,
    }
}

fn note_addressed_to(op: &Op, me: &str) -> bool {
    match op {
        Op::Note { to, .. } => match to {
            NoteTo::All => true,
            NoteTo::Checkout(name) => name == me,
            NoteTo::Changeset(_) | NoteTo::Entity(_) => true,
        },
        _ => false,
    }
}

pub fn inbox(repo: &Repo) -> Result<InboxOut> {
    let me = checkout_name(repo);
    let cursor = repo.redb().inbox_read_ix()?;
    let unread = repo
        .store()
        .ops(OpIx(0), false)?
        .into_iter()
        .filter(|(ix, e)| {
            ix.0 > cursor && note_is_mail(&e.op) && note_addressed_to(&e.op, &me)
        })
        .map(|(ix, e)| op_out(repo, ix, &e))
        .collect();
    Ok(InboxOut { unread, cursor })
}

/// `svc mail --read <n>`: mark notes through op `n` as read.
pub fn mail_read(repo: &Repo, ix: u64) -> Result<InboxOut> {
    repo.redb().set_inbox_read_ix(ix)?;
    inbox(repo)
}

fn claim_ids(repo: &Repo, spec: &str) -> Result<Vec<EntityId>> {
    if let Ok(id) = resolve_entity(repo, spec) {
        return Ok(vec![id]);
    }
    let snap = repo.current()?;
    let ids: Vec<EntityId> = snap
        .entities
        .iter()
        .filter(|(_, r)| r.file.as_str() == spec || r.file.as_str().ends_with(&format!("/{spec}")))
        .map(|(id, _)| *id)
        .collect();
    if ids.is_empty() {
        Err(Error::NotFound(format!(
            "{spec:?} is not an entity or a tracked file"
        )))
    } else {
        Ok(ids)
    }
}

pub fn claim(repo: &Repo, specs: &[String]) -> Result<Vec<MutationOut>> {
    if specs.is_empty() {
        return Err(Error::Other("claim: pass an entity or a file".into()));
    }
    let me = checkout_name(repo);
    let mut out = Vec::new();
    for spec in specs {
        for id in claim_ids(repo, spec)? {
            out.push(note(
                repo,
                NoteTo::Entity(id),
                NoteKind::Claim,
                me.clone(),
            )?);
        }
    }
    Ok(out)
}

pub fn release(repo: &Repo, specs: &[String]) -> Result<Vec<MutationOut>> {
    let me = checkout_name(repo);
    let ids = if specs.is_empty() {
        active_claims(repo)?
            .into_iter()
            .filter(|c| c.by == me)
            .map(|c| c.entity)
            .collect()
    } else {
        let mut ids = Vec::new();
        for spec in specs {
            ids.extend(claim_ids(repo, spec)?);
        }
        ids
    };
    let mut out = Vec::new();
    for id in ids {
        out.push(note(
            repo,
            NoteTo::Entity(id),
            NoteKind::Release,
            me.clone(),
        )?);
    }
    Ok(out)
}

/// Latest Claim/Release per entity; only live Claims remain.
pub fn active_claims(repo: &Repo) -> Result<Vec<ClaimOut>> {
    let mut last: BTreeMap<EntityId, (NoteKind, String)> = BTreeMap::new();
    for (ix, e) in repo.store().ops(OpIx(0), false)? {
        if let Op::Note {
            to: NoteTo::Entity(id),
            kind,
            ..
        } = &e.op
        {
            if matches!(kind, NoteKind::Claim | NoteKind::Release) {
                let by = repo
                    .redb()
                    .op_workspace(ix)
                    .ok()
                    .flatten()
                    .filter(|w| !w.is_empty())
                    .unwrap_or_else(|| DEFAULT_WORKSPACE.to_string());
                last.insert(*id, (kind.clone(), by));
            }
        }
    }
    let snap = repo.current()?;
    let mut out: Vec<ClaimOut> = last
        .into_iter()
        .filter_map(|(id, (kind, by))| {
            if kind != NoteKind::Claim {
                return None;
            }
            let name = snap
                .entities
                .get(&id)
                .map(|r| r.name.clone())
                .unwrap_or_else(|| id.short());
            Some(ClaimOut {
                entity: id,
                name,
                by,
            })
        })
        .collect();
    out.sort_by(|a, b| a.name.cmp(&b.name).then(a.by.cmp(&b.by)));
    Ok(out)
}

/// Notes hung on an entity (show-def / the other half of a review thread).
pub fn notes_about_entity(repo: &Repo, id: EntityId) -> Result<Vec<OpOut>> {
    Ok(repo
        .store()
        .ops(OpIx(0), true)?
        .into_iter()
        .filter(|(_, e)| {
            matches!(
                &e.op,
                Op::Note {
                    to: NoteTo::Entity(eid),
                    ..
                } if *eid == id
            )
        })
        .map(|(ix, e)| op_out(repo, ix, &e))
        .collect())
}

crates/svc-repo/src/replay.rs.Text:
//! O5 (the oracle set): replaying the op log from the root reproduces every snapshot. The replay
//! runs on a fresh store with no filesystem, so anything the verbs keep outside the op path
//! shows up as a divergence. Snapshot hashes include change ids, and `Branch`/`Merge` mint
//! theirs at run time, so equality is on **content** (`Snapshot::content_eq`) with ids mapped
//! as the replay goes.

use std::collections::BTreeMap;

use serde::Serialize;
use svc_core::engine::{add_def_at, delete, edit_def, inline, move_def, relocate, rename};
use svc_core::{
    ChangeId, Langs, MemStore, Op, OpIx, OpLogEntry, Result, Snapshot, SnapshotId, Store, View,
};

use crate::history::child_of;
use crate::merge::{lca, merged_snapshot};
use crate::repo::Repo;

#[derive(Clone, Debug, Serialize)]
pub struct ReplayReport {
    pub ops: usize,
    /// First op whose replayed result differs from the recorded `after.root`, if any.
    pub diverged_at: Option<OpIx>,
}

impl ReplayReport {
    pub fn ok(&self) -> bool {
        self.diverged_at.is_none()
    }
}

struct Replay<'a> {
    src: &'a dyn Store,
    store: MemStore,
    langs: &'a Langs,
    /// Recorded snapshot id → replayed snapshot id.
    snaps: BTreeMap<SnapshotId, SnapshotId>,
    changes: BTreeMap<ChangeId, ChangeId>,
}

impl Replay<'_> {
    fn change(&self, c: ChangeId) -> ChangeId {
        *self.changes.get(&c).unwrap_or(&c)
    }

    fn current(&self) -> Result<Snapshot> {
        self.store.get_snapshot(self.store.root()?)
    }

    fn commit(&self, snap: &Snapshot) -> Result<SnapshotId> {
        let id = self.store.put_snapshot(snap)?;
        self.store.set_head(snap.change, id)?;
        self.store.set_root(id)?;
        Ok(id)
    }

    fn amend(&self, cur: &Snapshot, mut next: Snapshot) -> Result<SnapshotId> {
        let cur_id = cur.id();
        if next.content_eq(cur) {
            return Ok(cur_id);
        }
        next.parents = cur.parents.clone();
        next.predecessors = vec![cur_id];
        next.change = cur.change;
        self.commit(&next)
    }

    /// Copy a recorded snapshot in (used for `Absorb`, whose result is data, not an op).
    fn import(&mut self, recorded: SnapshotId) -> Result<SnapshotId> {
        let mut snap = self.src.get_snapshot(recorded)?;
        snap.change = self.change(snap.change);
        snap.parents = snap.parents.iter().map(|p| *self.snaps.get(p).unwrap_or(p)).collect();
        snap.predecessors = snap.predecessors.iter().map(|p| *self.snaps.get(p).unwrap_or(p)).collect();
        for rec in snap.entities.values() {
            self.store.put_blob(&self.src.get_blob(&rec.content.0)?)?;
            self.store.put_blob(&self.src.get_blob(&rec.bytes.0)?)?;
        }
        self.commit(&snap)
    }

    fn restore(&self, view: &View) -> Result<()> {
        for (change, snap) in &view.heads {
            if let Some(mapped) = self.snaps.get(snap) {
                self.store.set_head(self.change(*change), *mapped)?;
            }
        }
        if let Some(root) = self.snaps.get(&view.root) {
            self.store.set_root(*root)?;
        }
        Ok(())
    }

    fn apply(&mut self, e: &OpLogEntry) -> Result<()> {
        // The entry records which root it started from. With several checkouts on one op
        // log (or a `checkout` between ops) that is not necessarily the last op's result:
        // switch to it first — a checkout switch, not a content change.
        if let Some(mapped) = self.snaps.get(&e.before.root).copied() {
            if mapped != self.store.root()? {
                self.store.set_root(mapped)?;
            }
        }
        let cur = self.current()?;
        match &e.op {
            Op::Rename { id, new } => {
                self.amend(&cur, rename(&cur, *id, new)?)?;
            }
            Op::Move { id, parent, ordinal } => {
                self.amend(&cur, move_def(&self.store, self.langs, &cur, *id, *parent, *ordinal)?)?;
            }
            Op::Relocate { id, file, ordinal } => {
                self.amend(&cur, relocate(&cur, &self.store, *id, file.clone(), *ordinal)?)?;
            }
            Op::Extract { id, new_parent, ordinal } => {
                self.amend(&cur, move_def(&self.store, self.langs, &cur, *id, *new_parent, Some(*ordinal))?)?;
            }
            Op::Inline { id } => {
                self.amend(&cur, inline(&self.store, self.langs, &cur, *id)?)?;
            }
            Op::AddDef { id, parent, ordinal, definition, intent, file } => {
                let next = add_def_at(&self.store, self.langs, &cur, *id, *parent, file.clone(), *ordinal, definition.as_bytes(), intent.clone())?;
                self.amend(&cur, next)?;
            }
            Op::Delete { id, .. } => {
                self.amend(&cur, delete(&cur, &self.store, *id)?)?;
            }
            Op::EditDef { id, definition, .. } => {
                let (next, _) = edit_def(&self.store, self.langs, &cur, *id, definition.as_bytes())?;
                self.amend(&cur, next)?;
            }
            Op::New { change } => {
                let c = self.change(*change);
                self.commit(&child_of(&cur, cur.id(), c))?;
            }
            Op::Describe { msg } => {
                let mut next = cur.clone();
                next.message = msg.clone();
                self.amend(&cur, next)?;
            }
            Op::Branch { .. } => {
                let recorded = self.src.get_snapshot(e.after.root)?;
                let c = self.fresh_change(recorded.change);
                let (base, base_id) = match cur.parents.first() {
                    Some(p) => (self.store.get_snapshot(*p)?, *p),
                    None => (cur.clone(), cur.id()),
                };
                self.commit(&child_of(&base, base_id, c))?;
            }
            Op::Merge { other } => {
                let other_id = self.store.head(self.change(*other))?;
                let cur_id = cur.id();
                let base_id = lca(&self.store, cur_id, other_id)?
                    .ok_or_else(|| svc_core::Error::Other("replay: no common ancestor".into()))?;
                let recorded = self.src.get_snapshot(e.after.root)?;
                let c = self.fresh_change(recorded.change);
                let snap = merged_snapshot(&self.store, self.langs, base_id, cur_id, other_id, c)?;
                self.commit(&snap)?;
            }
            Op::Undo | Op::Restore { .. } => self.restore(&e.after)?,
            Op::Resolve { conflict, take } => {
                let (next, _) = crate::merge::resolved_snapshot(&self.store, &cur, *conflict as usize, *take)?;
                self.amend(&cur, next)?;
            }
            Op::Absorb => {
                self.import(e.after.root)?;
            }
            Op::Note { .. } => {}
        }
        Ok(())
    }

    fn fresh_change(&mut self, recorded: ChangeId) -> ChangeId {
        let c = ChangeId::new();
        self.changes.insert(recorded, c);
        c
    }
}

/// Replay `repo`'s op log on a fresh store; report the first divergence.
pub fn replay(repo: &Repo) -> Result<ReplayReport> {
    let src = repo.store();
    let ops = src.ops(OpIx(0), false)?;
    let mut r = Replay {
        src,
        store: MemStore::new(),
        langs: repo.langs(),
        snaps: BTreeMap::new(),
        changes: BTreeMap::new(),
    };
    let mut diverged_at = None;
    for (i, (ix, e)) in ops.iter().enumerate() {
        if i == 0 {
            // The init op's `after.root` is the ingested tree; replay starts from it.
            r.import(e.after.root)?;
        } else {
            r.apply(e)?;
        }
        let got = r.current()?;
        let want = src.get_snapshot(e.after.root)?;
        r.snaps.insert(e.after.root, got.id());
        if !got.content_eq(&want) && diverged_at.is_none() {
            diverged_at = Some(*ix);
        }
    }
    Ok(ReplayReport {
        ops: ops.len(),
        diverged_at,
    })
}

crates/svc-repo/src/store.rs.Text:
//! `svc_core::Store` over one redb file. Snapshots and blobs are content-addressed and
//! immutable; only `root`, `heads`, branches and the changeset rows ever move.
//!
//! One file can back several checkouts (jj-style named workspaces, see `workspace.rs`).
//! Snapshots, heads, branches and the op log are shared; the checkout-scoped rows — `root`,
//! `render_pending`, `open_changeset` — live in `META` for the default checkout and in a
//! [`WorkspaceRow`] for a named one. Which set a `RedbStore` reads is fixed at open time.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use redb::{
    ConcurrencyMode, Database, ReadTransaction, ReadableDatabase, ReadableTable, TableDefinition,
    TableError, WriteTransaction,
};
use serde::{Deserialize, Serialize, de::DeserializeOwned};
use svc_core::{
    ChangeId, ChangeSet, ChangeSetId, Error, OpIx, OpLogEntry, OpenChangeSet, RelPath, Result,
    Snapshot, SnapshotId, Store, View,
};
use uuid::Uuid;

const OBJECTS: TableDefinition<&[u8; 32], &[u8]> = TableDefinition::new("objects");
const SNAPSHOTS: TableDefinition<&[u8; 32], &[u8]> = TableDefinition::new("snapshots");
const OPLOG: TableDefinition<u64, &[u8]> = TableDefinition::new("oplog");
const HEADS: TableDefinition<Uuid, &[u8; 32]> = TableDefinition::new("heads");
const CHANGESETS: TableDefinition<Uuid, &[u8]> = TableDefinition::new("changesets");
const BRANCHES: TableDefinition<&str, Uuid> = TableDefinition::new("branches");
/// Singleton rows: `root`, `open_changeset`, `render_pending`.
const META: TableDefinition<&str, &[u8]> = TableDefinition::new("meta");

/// Named checkouts: `name → WorkspaceRow`. The default checkout is not a row here.
const WORKSPACES: TableDefinition<&str, &[u8]> = TableDefinition::new("workspaces");
/// Which checkout appended each op (`OpIx → name`; the default checkout writes `""`).
/// `OpLogEntry` is a frozen `svc-core` shape, so attribution lives beside it, not in it.
const OP_WORKSPACE: TableDefinition<u64, &str> = TableDefinition::new("op_workspace");
/// `SnapshotId → {path → blake3 of the rendered file}`, filled the first time a snapshot is
/// rendered. Rendering is a pure function of the snapshot and the content-addressed objects,
/// so a row never goes stale; it lets `working_copy_clean` hash the tree instead of
/// re-rendering every entity on every verb.
const RENDERED: TableDefinition<&[u8; 32], &[u8]> = TableDefinition::new("rendered");

const META_ROOT: &str = "root";
const META_OPEN_CHANGESET: &str = "open_changeset";
const META_RENDER_PENDING: &str = "render_pending";

fn inbox_meta_key(workspace: Option<&str>) -> String {
    match workspace {
        None | Some("") => "inbox_read".into(),
        Some(name) => format!("inbox_read:{name}"),
    }
}

/// Everything a named checkout keeps that the default checkout keeps in `META`.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct WorkspaceRow {
    /// Absolute directory the checkout is rendered into.
    pub path: PathBuf,
    pub root: Option<SnapshotId>,
    pub render_pending: bool,
    pub open_changeset: Option<OpenChangeSet>,
}

/// Everything a verb writes, held back until `append_op`'s transaction: blobs, snapshots,
/// head/root/render-pending. A mutation is published in one redb txn — one fsync instead of
/// one per object, and a crash can never leave the store a snapshot ahead of the op log.
/// Reads consult it first, so the code in between (`amend`, `view`, the engine reading a
/// content it just put) sees what it just wrote.
///
/// `expected` is the view the verb computed from (`None` only for `Repo::init`, before a
/// view exists). Other processes share the store, so `append_op` compares the persisted
/// root and every head it is about to move against it inside the write transaction: two
/// processes that both read head H and both try to publish H→H' cannot both win — the
/// second finds H' and is refused with nothing written.
struct Staged {
    expected: Option<View>,
    blobs: std::collections::BTreeMap<[u8; 32], Vec<u8>>,
    snapshots: std::collections::BTreeMap<SnapshotId, Vec<u8>>,
    heads: std::collections::BTreeMap<ChangeId, SnapshotId>,
    root: Option<SnapshotId>,
    render_pending: Option<bool>,
}

pub struct RedbStore {
    db: Database,
    /// `None` = the default checkout (`META` rows); `Some(name)` = a `WORKSPACES` row.
    workspace: Option<String>,
    staged: std::sync::Mutex<Option<Staged>>,
    /// Decoded snapshots, by id. A snapshot is immutable, so a hit is always right; a verb
    /// asks for the current one several times and decoding 10k entities is the cost.
    decoded: std::sync::Mutex<BTreeMap<SnapshotId, Snapshot>>,
}

impl RedbStore {
    /// `MultiWriter`: opens never exclude each other (readers and writers in different
    /// checkouts share one store); each write transaction takes a byte-range lock on the file
    /// and readers follow commits. Linux, macOS and Windows only.
    fn open_or_create(path: &Path, create: bool) -> Result<Database> {
        let mut builder = Database::builder();
        builder.set_concurrency_mode(ConcurrencyMode::MultiWriter);
        if create {
            builder.create(path)
        } else {
            builder.open(path)
        }
        .map_err(Error::backend)
    }

    /// Creates the file and seeds every table, so readers never see `TableDoesNotExist`.
    pub fn create(path: &Path) -> Result<Self> {
        let db = Self::open_or_create(path, true)?;
        let store = Self { db, workspace: None, staged: Default::default(), decoded: Default::default() };
        store.write(|txn| {
            txn.open_table(OBJECTS).map_err(Error::backend)?;
            txn.open_table(SNAPSHOTS).map_err(Error::backend)?;
            txn.open_table(OPLOG).map_err(Error::backend)?;
            txn.open_table(HEADS).map_err(Error::backend)?;
            txn.open_table(CHANGESETS).map_err(Error::backend)?;
            txn.open_table(BRANCHES).map_err(Error::backend)?;
            txn.open_table(META).map_err(Error::backend)?;
            txn.open_table(WORKSPACES).map_err(Error::backend)?;
            txn.open_table(OP_WORKSPACE).map_err(Error::backend)?;
            txn.open_table(RENDERED).map_err(Error::backend)?;
            Ok(())
        })?;
        Ok(store)
    }

    /// The checkout that appended op `ix`: `Some("")` for the default one, `None` for ops
    /// written before attribution existed.
    pub fn op_workspace(&self, ix: OpIx) -> Result<Option<String>> {
        let txn = self.read()?;
        let table = match txn.open_table(OP_WORKSPACE) {
            Ok(t) => t,
            Err(TableError::TableDoesNotExist(_)) => return Ok(None),
            Err(e) => return Err(Error::backend(e)),
        };
        Ok(table
            .get(ix.0)
            .map_err(Error::backend)?
            .map(|g| g.value().to_string()))
    }

    /// Per-file hashes of `id` rendered, if some verb has rendered it before.
    pub fn rendered_hashes(&self, id: SnapshotId) -> Result<Option<BTreeMap<RelPath, [u8; 32]>>> {
        let txn = self.read()?;
        let table = match txn.open_table(RENDERED) {
            Ok(t) => t,
            Err(TableError::TableDoesNotExist(_)) => return Ok(None),
            Err(e) => return Err(Error::backend(e)),
        };
        match table.get(&id.0).map_err(Error::backend)? {
            Some(g) => Ok(Some(decode(g.value())?)),
            None => Ok(None),
        }
    }

    pub fn set_rendered_hashes(&self, id: SnapshotId, hashes: &BTreeMap<RelPath, [u8; 32]>) -> Result<()> {
        let bytes = encode(hashes)?;
        self.write(|txn| {
            let mut table = txn.open_table(RENDERED).map_err(Error::backend)?;
            table.insert(&id.0, bytes.as_slice()).map_err(Error::backend)?;
            Ok(())
        })
    }

    /// [`Store::append_op`] attributed to `workspace` (`None` = the default checkout) rather
    /// than to this handle's: a replayed history keeps the checkout each op came from.
    pub fn append_op_as(&self, e: &OpLogEntry, workspace: Option<&str>) -> Result<OpIx> {
        let bytes = encode(e)?;
        let ws = workspace.unwrap_or_default().to_string();
        let staged = self.staged.lock().unwrap().take();
        self.write(|txn| {
            // Publish what the verb staged together with the entry that describes it.
            if let Some(s) = &staged {
                // Compare-and-swap against the view the verb read: another process may have
                // published since. A mismatch aborts the transaction with nothing written.
                let expected = s.expected.as_ref();
                if let Some(v) = expected
                    && self.root_in(txn)? != Some(v.root)
                {
                    return Err(Error::Other(
                        "concurrent update: this checkout's root moved under the verb; nothing was written — run the verb again"
                            .into(),
                    ));
                }
                if !s.blobs.is_empty() {
                    let mut table = txn.open_table(OBJECTS).map_err(Error::backend)?;
                    for (id, bytes) in &s.blobs {
                        table.insert(id, bytes.as_slice()).map_err(Error::backend)?;
                    }
                }
                if !s.snapshots.is_empty() {
                    let mut table = txn.open_table(SNAPSHOTS).map_err(Error::backend)?;
                    for (id, bytes) in &s.snapshots {
                        table.insert(&id.0, bytes.as_slice()).map_err(Error::backend)?;
                    }
                }
                if !s.heads.is_empty() {
                    let mut heads = txn.open_table(HEADS).map_err(Error::backend)?;
                    for (c, snap) in &s.heads {
                        let actual = heads
                            .get(c.as_uuid())
                            .map_err(Error::backend)?
                            .map(|g| SnapshotId(*g.value()));
                        if expected.is_some_and(|v| actual != v.heads.get(c).copied()) {
                            return Err(Error::Other(format!(
                                "concurrent update: change {} moved to {} under the verb; nothing was written (run `svc workspace update-stale`)",
                                c.short(),
                                actual.map(|a| a.short()).unwrap_or_else(|| "nothing".into())
                            )));
                        }
                        heads.insert(c.as_uuid(), &snap.0).map_err(Error::backend)?;
                    }
                }
                match &self.workspace {
                    None => {
                        if let Some(r) = s.root {
                            self.set_meta_in(txn, META_ROOT, &r)?;
                        }
                        if let Some(p) = s.render_pending {
                            self.set_meta_in(txn, META_RENDER_PENDING, &p)?;
                        }
                    }
                    Some(name) if s.root.is_some() || s.render_pending.is_some() => {
                        self.update_own_row_in(txn, name, |r| {
                            if let Some(id) = s.root {
                                r.root = Some(id);
                            }
                            if let Some(p) = s.render_pending {
                                r.render_pending = p;
                            }
                        })?;
                    }
                    Some(_) => {}
                }
            }
            let mut table = txn.open_table(OPLOG).map_err(Error::backend)?;
            let next = table
                .last()
                .map_err(Error::backend)?
                .map(|(k, _)| k.value() + 1)
                .unwrap_or(0);
            table.insert(next, bytes.as_slice()).map_err(Error::backend)?;
            let mut by = txn.open_table(OP_WORKSPACE).map_err(Error::backend)?;
            by.insert(next, ws.as_str()).map_err(Error::backend)?;
            Ok(OpIx(next))
        })
    }

    /// `ops(since, rev)` restricted to what this handle's checkout appended (unattributed
    /// ops count as the default checkout's).
    pub fn own_ops(&self, since: OpIx, rev: bool) -> Result<Vec<(OpIx, OpLogEntry)>> {
        let me = self.workspace.clone().unwrap_or_default();
        let mut out = Vec::new();
        for (ix, e) in self.ops(since, rev)? {
            if self.op_workspace(ix)?.unwrap_or_default() == me {
                out.push((ix, e));
            }
        }
        Ok(out)
    }

    pub fn open(path: &Path) -> Result<Self> {
        let db = Self::open_or_create(path, false)?;
        Ok(Self { db, workspace: None, staged: Default::default(), decoded: Default::default() })
    }

    /// Re-scope this handle to checkout `name` (`None` = default). The row must exist.
    pub fn with_workspace(mut self, name: Option<&str>) -> Result<Self> {
        if let Some(n) = name {
            self.workspace_row(n)?
                .ok_or_else(|| Error::NotFound(format!("workspace {n:?}")))?;
        }
        self.workspace = name.map(str::to_string);
        Ok(self)
    }

    /// Hold every write until the next `append_op`, which publishes them with the op in one
    /// transaction. `Repo::mutate` brackets every verb with this.
    pub fn stage(&self, expected: Option<&View>) {
        *self.staged.lock().unwrap() = Some(Staged {
            expected: expected.cloned(),
            blobs: Default::default(),
            snapshots: Default::default(),
            heads: Default::default(),
            root: None,
            render_pending: None,
        });
    }

    /// Drop everything staged since `stage()`: the verb failed and nothing was written.
    pub fn discard_staged(&self) {
        *self.staged.lock().unwrap() = None;
    }

    fn staged_head(&self, id: ChangeId) -> Option<SnapshotId> {
        self.staged.lock().unwrap().as_ref().and_then(|s| s.heads.get(&id).copied())
    }

    fn staged_root(&self) -> Option<SnapshotId> {
        self.staged.lock().unwrap().as_ref().and_then(|s| s.root)
    }

    fn staged_render_pending(&self) -> Option<bool> {
        self.staged.lock().unwrap().as_ref().and_then(|s| s.render_pending)
    }

    /// Record instead of writing when staging is on. Returns whether it was recorded.
    fn stage_with(&self, f: impl FnOnce(&mut Staged)) -> bool {
        match self.staged.lock().unwrap().as_mut() {
            Some(s) => {
                f(s);
                true
            }
            None => false,
        }
    }

    /// A checkout-row update inside an open write transaction.
    fn update_own_row_in(&self, txn: &WriteTransaction, name: &str, f: impl FnOnce(&mut WorkspaceRow)) -> Result<()> {
        let mut table = txn.open_table(WORKSPACES).map_err(Error::backend)?;
        let mut row: WorkspaceRow = match table.get(name).map_err(Error::backend)? {
            Some(g) => decode(g.value())?,
            None => return Err(Error::NotFound(format!("workspace {name:?}"))),
        };
        f(&mut row);
        let bytes = encode(&row)?;
        table.insert(name, bytes.as_slice()).map_err(Error::backend)?;
        Ok(())
    }

    fn set_meta_in<T: Serialize>(&self, txn: &WriteTransaction, key: &str, value: &T) -> Result<()> {
        let bytes = encode(value)?;
        let mut table = txn.open_table(META).map_err(Error::backend)?;
        table.insert(key, bytes.as_slice()).map_err(Error::backend)?;
        Ok(())
    }

    /// This checkout's persisted `root`, read inside an open write transaction (never staged).
    fn root_in(&self, txn: &WriteTransaction) -> Result<Option<SnapshotId>> {
        match &self.workspace {
            None => {
                let table = txn.open_table(META).map_err(Error::backend)?;
                match table.get(META_ROOT).map_err(Error::backend)? {
                    Some(g) => Ok(Some(decode(g.value())?)),
                    None => Ok(None),
                }
            }
            Some(name) => {
                let table = txn.open_table(WORKSPACES).map_err(Error::backend)?;
                match table.get(name.as_str()).map_err(Error::backend)? {
                    Some(g) => Ok(decode::<WorkspaceRow>(g.value())?.root),
                    None => Err(Error::NotFound(format!("workspace {name:?}"))),
                }
            }
        }
    }

    /// The checkout this handle's `root`/`render_pending`/`open_changeset` refer to.
    pub fn workspace(&self) -> Option<&str> {
        self.workspace.as_deref()
    }

    /// Last `svc mail --read` op index for this checkout (0 = nothing marked).
    pub fn inbox_read_ix(&self) -> Result<u64> {
        Ok(self.get_meta::<u64>(&inbox_meta_key(self.workspace.as_deref()))?.unwrap_or(0))
    }

    pub fn set_inbox_read_ix(&self, ix: u64) -> Result<()> {
        self.set_meta(&inbox_meta_key(self.workspace.as_deref()), &ix)
    }

    /// Every named checkout, sorted by name. Stores created before the table existed read
    /// as empty rather than failing.
    pub fn workspaces(&self) -> Result<Vec<(String, WorkspaceRow)>> {
        let txn = self.read()?;
        let table = match txn.open_table(WORKSPACES) {
            Ok(t) => t,
            Err(TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
            Err(e) => return Err(Error::backend(e)),
        };
        let mut out = Vec::new();
        for row in table.iter().map_err(Error::backend)? {
            let (k, v) = row.map_err(Error::backend)?;
            out.push((k.value().to_string(), decode(v.value())?));
        }
        Ok(out)
    }

    pub fn workspace_row(&self, name: &str) -> Result<Option<WorkspaceRow>> {
        Ok(self
            .workspaces()?
            .into_iter()
            .find(|(n, _)| n == name)
            .map(|(_, row)| row))
    }

    pub fn set_workspace_row(&self, name: &str, row: &WorkspaceRow) -> Result<()> {
        let bytes = encode(row)?;
        self.write(|txn| {
            let mut table = txn.open_table(WORKSPACES).map_err(Error::backend)?;
            table.insert(name, bytes.as_slice()).map_err(Error::backend)?;
            Ok(())
        })
    }

    /// Drops the row; returns whether it existed. The files on disk are untouched.
    pub fn remove_workspace(&self, name: &str) -> Result<bool> {
        self.write(|txn| {
            let mut table = txn.open_table(WORKSPACES).map_err(Error::backend)?;
            Ok(table.remove(name).map_err(Error::backend)?.is_some())
        })
    }

    /// The default checkout's `root`, whatever this handle is scoped to.
    pub fn default_root(&self) -> Result<Option<SnapshotId>> {
        self.get_meta::<SnapshotId>(META_ROOT)
    }

    /// This handle's row, when scoped to a named checkout.
    fn own_row(&self, name: &str) -> Result<WorkspaceRow> {
        self.workspace_row(name)?
            .ok_or_else(|| Error::NotFound(format!("workspace {name:?}")))
    }

    fn update_own_row(&self, name: &str, f: impl FnOnce(&mut WorkspaceRow)) -> Result<()> {
        let mut row = self.own_row(name)?;
        f(&mut row);
        self.set_workspace_row(name, &row)
    }

    /// True when the failure is redb's cross-process lock, the one case worth retrying.
    fn read(&self) -> Result<ReadTransaction> {
        self.db.begin_read().map_err(Error::backend)
    }

    fn write<R>(&self, f: impl FnOnce(&WriteTransaction) -> Result<R>) -> Result<R> {
        let txn = self.db.begin_write().map_err(Error::backend)?;
        let out = f(&txn)?;
        txn.commit().map_err(Error::backend)?;
        Ok(out)
    }

    fn get_meta<T: DeserializeOwned>(&self, key: &str) -> Result<Option<T>> {
        let txn = self.read()?;
        let table = txn.open_table(META).map_err(Error::backend)?;
        match table.get(key).map_err(Error::backend)? {
            Some(g) => Ok(Some(decode(g.value())?)),
            None => Ok(None),
        }
    }

    fn set_meta<T: Serialize>(&self, key: &str, value: &T) -> Result<()> {
        let bytes = encode(value)?;
        self.write(|txn| {
            let mut table = txn.open_table(META).map_err(Error::backend)?;
            table.insert(key, bytes.as_slice()).map_err(Error::backend)?;
            Ok(())
        })
    }
}

fn encode<T: Serialize>(value: &T) -> Result<Vec<u8>> {
    postcard::to_stdvec(value).map_err(|e| Error::Other(e.to_string()))
}

fn decode<T: DeserializeOwned>(bytes: &[u8]) -> Result<T> {
    postcard::from_bytes(bytes).map_err(|e| Error::Other(e.to_string()))
}

fn hex32(bytes: &[u8; 32]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

impl Store for RedbStore {
    fn put_blob(&self, bytes: &[u8]) -> Result<[u8; 32]> {
        let id = *blake3::hash(bytes).as_bytes();
        if self.stage_with(|s| {
            s.blobs.insert(id, bytes.to_vec());
        }) {
            return Ok(id);
        }
        self.write(|txn| {
            let mut table = txn.open_table(OBJECTS).map_err(Error::backend)?;
            table.insert(&id, bytes).map_err(Error::backend)?;
            Ok(())
        })?;
        Ok(id)
    }

    fn get_blob(&self, id: &[u8; 32]) -> Result<Vec<u8>> {
        if let Some(b) = self.staged.lock().unwrap().as_ref().and_then(|s| s.blobs.get(id)) {
            return Ok(b.clone());
        }
        let txn = self.read()?;
        let table = txn.open_table(OBJECTS).map_err(Error::backend)?;
        table
            .get(id)
            .map_err(Error::backend)?
            .map(|g| g.value().to_vec())
            .ok_or_else(|| Error::NotFound(hex32(id)))
    }

    fn put_snapshot(&self, s: &Snapshot) -> Result<SnapshotId> {
        let id = s.id();
        let bytes = encode(s)?;
        if self.stage_with(|st| {
            st.snapshots.insert(id, bytes.clone());
        }) {
            return Ok(id);
        }
        self.write(|txn| {
            let mut table = txn.open_table(SNAPSHOTS).map_err(Error::backend)?;
            table.insert(&id.0, bytes.as_slice()).map_err(Error::backend)?;
            Ok(())
        })?;
        Ok(id)
    }

    fn get_snapshot(&self, id: SnapshotId) -> Result<Snapshot> {
        if let Some(s) = self.decoded.lock().unwrap().get(&id) {
            return Ok(s.clone());
        }
        // A held snapshot is not cached: it is gone if the verb is discarded.
        if let Some(b) = self.staged.lock().unwrap().as_ref().and_then(|s| s.snapshots.get(&id)) {
            return decode(b);
        }
        let txn = self.read()?;
        let table = txn.open_table(SNAPSHOTS).map_err(Error::backend)?;
        let snap: Snapshot = match table.get(&id.0).map_err(Error::backend)? {
            Some(g) => decode(g.value())?,
            None => return Err(Error::NoSuchSnapshot),
        };
        let mut decoded = self.decoded.lock().unwrap();
        if decoded.len() >= 8 {
            decoded.clear();
        }
        decoded.insert(id, snap.clone());
        Ok(snap)
    }

    fn append_op(&self, e: &OpLogEntry) -> Result<OpIx> {
        self.append_op_as(e, self.workspace.as_deref())
    }

    fn ops(&self, since: OpIx, rev: bool) -> Result<Vec<(OpIx, OpLogEntry)>> {
        let txn = self.read()?;
        let table = txn.open_table(OPLOG).map_err(Error::backend)?;
        let mut out = Vec::new();
        for row in table.range(since.0..).map_err(Error::backend)? {
            let (k, v) = row.map_err(Error::backend)?;
            out.push((OpIx(k.value()), decode(v.value())?));
        }
        if rev {
            out.reverse();
        }
        Ok(out)
    }

    fn head(&self, id: ChangeId) -> Result<SnapshotId> {
        if let Some(s) = self.staged_head(id) {
            return Ok(s);
        }
        let txn = self.read()?;
        let table = txn.open_table(HEADS).map_err(Error::backend)?;
        table
            .get(id.as_uuid())
            .map_err(Error::backend)?
            .map(|g| SnapshotId(*g.value()))
            .ok_or(Error::NoSuchChange(id))
    }

    fn set_head(&self, id: ChangeId, snap: SnapshotId) -> Result<()> {
        if self.stage_with(|s| {
            s.heads.insert(id, snap);
        }) {
            return Ok(());
        }
        self.write(|txn| {
            let mut table = txn.open_table(HEADS).map_err(Error::backend)?;
            table
                .insert(id.as_uuid(), &snap.0)
                .map_err(Error::backend)?;
            Ok(())
        })
    }

    fn heads(&self) -> Result<Vec<(ChangeId, SnapshotId)>> {
        let txn = self.read()?;
        let table = txn.open_table(HEADS).map_err(Error::backend)?;
        let mut out = Vec::new();
        for row in table.iter().map_err(Error::backend)? {
            let (k, v) = row.map_err(Error::backend)?;
            out.push((ChangeId(k.value()), SnapshotId(*v.value())));
        }
        if let Some(s) = self.staged.lock().unwrap().as_ref() {
            for (c, snap) in &s.heads {
                match out.iter_mut().find(|(k, _)| k == c) {
                    Some(slot) => slot.1 = *snap,
                    None => out.push((*c, *snap)),
                }
            }
        }
        Ok(out)
    }

    fn evolog(&self, id: ChangeId) -> Result<Vec<Snapshot>> {
        let mut cur = self.head(id)?;
        let mut out = Vec::new();
        loop {
            let snap = self.get_snapshot(cur)?;
            let next = snap.predecessors.first().copied();
            out.push(snap);
            match next {
                Some(p) => cur = p,
                None => break,
            }
        }
        Ok(out)
    }

    fn put_changeset(&self, cs: &ChangeSet) -> Result<()> {
        let bytes = encode(cs)?;
        self.write(|txn| {
            let mut table = txn.open_table(CHANGESETS).map_err(Error::backend)?;
            table
                .insert(cs.id.as_uuid(), bytes.as_slice())
                .map_err(Error::backend)?;
            Ok(())
        })
    }

    fn get_changeset(&self, id: ChangeSetId) -> Result<ChangeSet> {
        let txn = self.read()?;
        let table = txn.open_table(CHANGESETS).map_err(Error::backend)?;
        match table.get(id.as_uuid()).map_err(Error::backend)? {
            Some(g) => decode(g.value()),
            None => Err(Error::NotFound(id.to_string())),
        }
    }

    fn changesets(&self) -> Result<Vec<ChangeSet>> {
        let txn = self.read()?;
        let table = txn.open_table(CHANGESETS).map_err(Error::backend)?;
        let mut out = Vec::new();
        for row in table.iter().map_err(Error::backend)? {
            let (_, v) = row.map_err(Error::backend)?;
            out.push(decode(v.value())?);
        }
        Ok(out)
    }

    fn set_branch(&self, name: &str, id: ChangeId) -> Result<()> {
        self.write(|txn| {
            let mut table = txn.open_table(BRANCHES).map_err(Error::backend)?;
            table.insert(name, id.as_uuid()).map_err(Error::backend)?;
            Ok(())
        })
    }

    fn branch(&self, name: &str) -> Result<Option<ChangeId>> {
        let txn = self.read()?;
        let table = txn.open_table(BRANCHES).map_err(Error::backend)?;
        Ok(table
            .get(name)
            .map_err(Error::backend)?
            .map(|g| ChangeId(g.value())))
    }

    fn branches(&self) -> Result<Vec<(String, ChangeId)>> {
        let txn = self.read()?;
        let table = txn.open_table(BRANCHES).map_err(Error::backend)?;
        let mut out = Vec::new();
        for row in table.iter().map_err(Error::backend)? {
            let (k, v) = row.map_err(Error::backend)?;
            out.push((k.value().to_string(), ChangeId(v.value())));
        }
        Ok(out)
    }

    fn resolve_prefix(&self, prefix: &str) -> Result<ChangeId> {
        let p = prefix.to_ascii_lowercase();
        let hex = p.replace('-', "");
        let mut hits: Vec<ChangeId> = self
            .heads()?
            .into_iter()
            .map(|(id, _)| id)
            .filter(|id| id.short().starts_with(&p) || id.to_string().replace('-', "").starts_with(&hex))
            .collect();
        hits.sort();
        hits.dedup();
        match hits.len() {
            1 => Ok(hits[0]),
            0 => Err(Error::NotFound(format!("prefix {prefix}"))),
            _ => Err(Error::AmbiguousPrefix {
                prefix: prefix.into(),
                candidates: hits,
            }),
        }
    }

    fn root(&self) -> Result<SnapshotId> {
        if let Some(r) = self.staged_root() {
            return Ok(r);
        }
        match &self.workspace {
            None => self.get_meta::<SnapshotId>(META_ROOT)?,
            Some(ws) => self.own_row(ws)?.root,
        }
        .ok_or(Error::NoSuchSnapshot)
    }

    fn set_root(&self, id: SnapshotId) -> Result<()> {
        if self.stage_with(|s| s.root = Some(id)) {
            return Ok(());
        }
        match &self.workspace {
            None => self.set_meta(META_ROOT, &id),
            Some(ws) => self.update_own_row(ws, |r| r.root = Some(id)),
        }
    }

    fn open_changeset(&self) -> Result<Option<OpenChangeSet>> {
        match &self.workspace {
            None => Ok(self
                .get_meta::<Option<OpenChangeSet>>(META_OPEN_CHANGESET)?
                .flatten()),
            Some(ws) => Ok(self.own_row(ws)?.open_changeset),
        }
    }

    fn set_open_changeset(&self, row: Option<OpenChangeSet>) -> Result<()> {
        match &self.workspace {
            None => self.set_meta(META_OPEN_CHANGESET, &row),
            Some(ws) => self.update_own_row(ws, |r| r.open_changeset = row),
        }
    }

    fn render_pending(&self) -> Result<bool> {
        if let Some(p) = self.staged_render_pending() {
            return Ok(p);
        }
        match &self.workspace {
            None => Ok(self
                .get_meta::<bool>(META_RENDER_PENDING)?
                .unwrap_or(false)),
            Some(ws) => Ok(self.own_row(ws)?.render_pending),
        }
    }

    fn set_render_pending(&self, v: bool) -> Result<()> {
        if self.stage_with(|s| s.render_pending = Some(v)) {
            return Ok(());
        }
        match &self.workspace {
            None => self.set_meta(META_RENDER_PENDING, &v),
            Some(ws) => self.update_own_row(ws, |r| r.render_pending = v),
        }
    }
}

